#include <iostream>
using namespace std;

template <typename T>
void show(T x) {
    cout << "通用那一份：料是 " << x << endl;
}

template <>
void show<bool>(bool x) {
    cout << "小灶那一份：料是 " << (x ? "对" : "错") << endl;
}

int main() {
    show(7);
    show(2.5);
    show(true);
    show(false);
    return 0;
}

